// Simplified Mint AI List Builder module
// Encapsulates AI modal wiring, preview, generate, and insert behavior.

import { escapeHtml, hasValidImageUrl, loadImageForRow } from './images.js?v=20260322n';

const AI_PREVIEW_PLACEHOLDER = 'Paste or edit here, one pair per line: English, Korean';

// Sentence data generated by the sentence step. One entry per word: { eng, kor, example, ex_kor }.
let sentenceData = [];

function extractAiText(payload) {
  const candidates = [
    payload?.result,
    payload?.text,
    payload?.data?.result,
    payload?.data?.text,
    payload?.choices?.[0]?.message?.content,
    payload?.data?.choices?.[0]?.message?.content
  ];
  const pick = candidates.find(v => typeof v === 'string' && v.trim());
  return pick ? pick.trim() : '';
}

async function fetchOpenAiText(prompt) {
  const body = JSON.stringify({ prompt });
  const attempts = [
    () => WillenaAPI.fetch('/.netlify/functions/openai_proxy', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body
    }),
    () => fetch('https://willena-proxy.willena.workers.dev/.netlify/functions/openai_proxy', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body,
      credentials: 'include'
    }),
    () => fetch('https://api.willenaenglish.com/.netlify/functions/openai_proxy', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body,
      credentials: 'include'
    })
  ];

  let lastError = '';
  for (const call of attempts) {
    try {
      const res = await call();
      const js = await res.json().catch(() => ({}));
      const text = extractAiText(js);
      if (res.ok && text) return text;
      lastError = (js && (js.error || js.message)) ? String(js.error || js.message) : `HTTP ${res.status}`;
    } catch (e) {
      lastError = e?.message || String(e);
    }
  }
  throw new Error(lastError || 'AI response was empty.');
}

/** Build sentence generation prompt */
function buildSentencePrompt(words, { mode, difficulty, patternDesc, patternExamples }) {
  const wordListStr = words.map(w => w.eng).join(', ');
  const count = words.length;

  const difficultyGuide = {
    easy:   'Use simple, short sentences (3-5 words). Use basic vocabulary appropriate for young learners.',
    medium: 'Use moderate sentences (5-8 words). Use everyday vocabulary appropriate for intermediate learners.',
    hard:   'Use longer, more complex sentences (8-12 words). Use varied vocabulary and more detailed context.'
  };
  const diffDesc = difficultyGuide[difficulty] || difficultyGuide.easy;

  const commonRules = [
    `Generate exactly ${count} example sentences, one for each of these English words: ${wordListStr}.`,
    diffDesc,
    'Each sentence MUST be a complete, natural English sentence ending with a period.',
    'Do NOT use quotation marks inside sentences. Do NOT use sentence fragments.',
    'Each sentence should clearly use the target word in a natural context.',
    'Keep sentences appropriate for ESL students (ages 8-15).',
    `Output format: one line per word, formatted as: word | English sentence | Korean translation`,
    'Do NOT number the lines. Do NOT add any extra text or explanation.'
  ];

  if (mode === 'pattern' && patternDesc) {
    const patternRules = [
      `The teacher wants sentences following this grammar pattern: ${patternDesc}`,
    ];
    if (patternExamples) {
      patternRules.push(`Here are example sentences the teacher provided as a model: ${patternExamples}`);
      patternRules.push('Follow the style and structure of these examples closely.');
    }
    return [...patternRules, ...commonRules].join('\n');
  }

  return [
    'Generate natural, varied example sentences for vocabulary practice.',
    ...commonRules
  ].join('\n');
}

/** Parse AI sentence output into array of { eng, example, ex_kor } */
function parseSentenceOutput(text, words) {
  const lines = text.split(/\r?\n/).map(l => l.trim()).filter(Boolean);
  const results = [];

  for (const line of lines) {
    // Try pipe-delimited format: word | sentence | korean
    const parts = line.split('|').map(s => s.trim());
    if (parts.length >= 3) {
      results.push({ eng: parts[0], example: parts[1], ex_kor: parts[2] });
      continue;
    }
    // Fallback: try to match any remaining lines with comma or tab
    const tabParts = line.split(/\t/).map(s => s.trim());
    if (tabParts.length >= 3) {
      results.push({ eng: tabParts[0], example: tabParts[1], ex_kor: tabParts[2] });
    }
  }

  // Best-effort match: align results back to original words by position
  const matched = [];
  for (let i = 0; i < words.length; i++) {
    const wordEng = words[i].eng.toLowerCase().trim();
    // Try exact word match first
    let found = results.find(r => r.eng.toLowerCase().trim() === wordEng);
    if (!found && i < results.length) found = results[i]; // fallback positional
    matched.push({
      eng: words[i].eng,
      kor: words[i].kor || '',
      example: found?.example || '',
      ex_kor: found?.ex_kor || ''
    });
  }
  return matched;
}

export function initMintAiListBuilder({
  getList,
  addItems, // (items) => {from, to}
  render,
  enablePicturesEl,
  enableDefinitionsEl,
  enableExamplesEl,
  loadingImages,
  generateDefinitionForRow,
  generateExampleForRow
}) {
  // Elements
  const aiLink = document.getElementById('aiListBuilderLink');
  const aiModal = document.getElementById('mintAiSimpleModal');
  const aiCloseBtn = document.getElementById('mintAiSimpleClose');
  const aiCancelBtn = document.getElementById('mintAiCancel');
  const aiInsertBtn = document.getElementById('mintAiInsert');
  const aiModeTopic = document.getElementById('mintAiModeTopic');
  const aiModeText = document.getElementById('mintAiModeText');
  const aiTopic = document.getElementById('mintAiTopic');
  const aiPassage = document.getElementById('mintAiPassage');
  const aiNum = document.getElementById('mintAiNum');
  const aiDiff = document.getElementById('mintAiDifficulty');
  const aiGenerateBtn = document.getElementById('mintAiGenerate');
  const aiClearBtn = document.getElementById('mintAiClear');
  const aiWordlist = document.getElementById('mintAiWordlist');
  const aiPreview = document.getElementById('mintAiPreview');
  const aiTitleInput = document.getElementById('mintAiSimpleBoxTitle');

  // Sentence generation elements
  const sentSection = document.getElementById('mintAiSentenceSection');
  const sentAutoBtn = document.getElementById('mintAiSentAuto');
  const sentPatternBtn = document.getElementById('mintAiSentPattern');
  const sentPatternWrap = document.getElementById('mintAiPatternInputWrap');
  const sentPatternDesc = document.getElementById('mintAiPatternDesc');
  const sentPatternExamples = document.getElementById('mintAiPatternExamples');
  const sentDiff = document.getElementById('mintAiSentDifficulty');
  const sentGenerateBtn = document.getElementById('mintAiSentGenerate');

  // Sentence mode toggle
  let sentenceMode = 'auto'; // 'auto' | 'pattern'

  const showAiModal = () => {
    if (aiModal) aiModal.style.display = 'flex';
    sentenceData = [];
  };
  const hideAiModal = () => {
    if (aiModal) aiModal.style.display = 'none';
    sentenceData = [];
  };

  if (aiLink && aiModal) aiLink.onclick = (e) => { e.preventDefault(); showAiModal(); };
  if (aiCloseBtn) aiCloseBtn.onclick = hideAiModal;
  if (aiCancelBtn) aiCancelBtn.onclick = hideAiModal;

  // Sentence auto/pattern toggle
  if (sentAutoBtn && sentPatternBtn) {
    sentAutoBtn.onclick = () => {
      sentAutoBtn.classList.add('active');
      sentPatternBtn.classList.remove('active');
      if (sentPatternWrap) sentPatternWrap.style.display = 'none';
      sentenceMode = 'auto';
    };
    sentPatternBtn.onclick = () => {
      sentPatternBtn.classList.add('active');
      sentAutoBtn.classList.remove('active');
      if (sentPatternWrap) sentPatternWrap.style.display = '';
      sentenceMode = 'pattern';
    };
  }

  if (aiModeTopic && aiModeText) {
    aiModeTopic.onclick = () => {
      aiModeTopic.classList.add('active');
      aiModeText.classList.remove('active');
      aiTopic.style.display = '';
      aiPassage.style.display = 'none';
    };
    aiModeText.onclick = () => {
      aiModeText.classList.add('active');
      aiModeTopic.classList.remove('active');
      aiTopic.style.display = 'none';
      aiPassage.style.display = '';
    };
  }

  function parseLinesToPairs(text) {
    const lines = (text || '').split(/\r?\n/).map(l => l.trim()).filter(Boolean);
    const out = [];
    for (const line of lines) {
      const cleaned = line
        .replace(/^\s*[-*\u2022]?\s*\d+[).]\s*/, '')
        .replace(/^[-*\u2022]\s*/, '');
      const [eng, kor] = cleaned.split(/\s*,\s*/);
      if (eng) out.push({ eng, kor: kor || '' });
    }
    return out;
  }

  /** Render preview — shows word pairs or word+sentence data depending on state */
  function renderAiPreviewFromWordlist() {
    const items = parseLinesToPairs(aiWordlist.value);
    if (!aiPreview) return;
    aiPreview.textContent = '';

    // If we have sentence data, show enriched preview
    if (sentenceData.length) {
      renderSentencePreview(items);
      return;
    }

    if (!items.length) { aiPreview.textContent = AI_PREVIEW_PLACEHOLDER; return; }
    aiPreview.innerHTML = items
      .map(({eng, kor}) => `<div>${escapeHtml(eng)}${kor? ', ' + escapeHtml(kor):''}</div>`)
      .join('');
  }

  /** Render preview with sentence data (stacked layout) */
  function renderSentencePreview(wordPairs) {
    if (!aiPreview) return;
    const items = wordPairs.length ? wordPairs : parseLinesToPairs(aiWordlist.value);
    if (!items.length) { aiPreview.textContent = AI_PREVIEW_PLACEHOLDER; return; }

    aiPreview.innerHTML = items.map((w, i) => {
      const sd = sentenceData[i] || {};
      const ex = sd.example || '';
      const exKor = sd.ex_kor || '';
      return `<div class="sent-item" data-idx="${i}">
        <div class="sent-eng">${escapeHtml(w.eng)}${w.kor ? ' <span class="sent-kor">(' + escapeHtml(w.kor) + ')</span>' : ''}</div>
        ${ex ? '<div class="sent-ex">' + escapeHtml(ex) + '</div>' : ''}
        ${exKor ? '<div class="sent-ex-kor">' + escapeHtml(exKor) + '</div>' : ''}
      </div>`;
    }).join('');
  }

  /** Show sentence section after words are available */
  function showSentenceSection() {
    if (sentSection) sentSection.style.display = '';
  }

  if (aiWordlist) aiWordlist.addEventListener('input', renderAiPreviewFromWordlist);
  if (aiPreview) {
    const syncPreviewToWordlist = () => {
      const rawText = (aiPreview.textContent || '').trim();
      if (!rawText || rawText === AI_PREVIEW_PLACEHOLDER) { aiWordlist.value = ''; return; }
      const lines = Array.from(aiPreview.childNodes).map(node => {
        if (node.nodeType === Node.TEXT_NODE) return String(node.textContent || '').trim();
        if (node.nodeType === Node.ELEMENT_NODE) return String(node.textContent || '').trim();
        return '';
      }).filter(Boolean);
      const text = lines.length ? lines.join('\n') : (aiPreview.textContent || '')
        .split(/\r?\n/).map(s=>s.trim()).filter(Boolean).join('\n');
      aiWordlist.value = text;
    };
    aiPreview.addEventListener('input', syncPreviewToWordlist);
    aiPreview.addEventListener('paste', () => setTimeout(syncPreviewToWordlist, 0));
  }

  if (aiGenerateBtn) aiGenerateBtn.onclick = async () => {
    if (!aiPreview) return;
    aiPreview.textContent = 'Generating…';
    sentenceData = []; // Reset sentences on new word generation
    const useText = aiModeText?.classList.contains('active');
    const n = Math.max(1, Math.min(30, parseInt(aiNum?.value || '10', 10)));
    const diff = aiDiff?.value || 'easy';
    const topic = (aiTopic?.value || '').trim();
    const passage = (aiPassage?.value || '').trim();
    const prompt = useText
      ? `From this passage, extract ${n} English-Korean word pairs (level: ${diff}). Format 'english, korean' per line. Passage:\n\n${passage}`
      : `Generate ${n} English-Korean word pairs (level: ${diff}) about the topic "${topic || 'everyday objects'}". Format 'english, korean' per line.`;
    try {
      const text = await fetchOpenAiText(prompt);
      aiWordlist.value = text;
      renderAiPreviewFromWordlist();
      showSentenceSection();

      // Now invent a short title using AI
      let titlePrompt;
      if (useText && passage) {
        titlePrompt = `Invent a short, catchy title (2-3 words only) for a vocabulary box based on this passage: \n${passage}`;
      } else if (topic) {
        titlePrompt = `Invent a short, catchy title (2-3 words only) for a vocabulary box about the topic: ${topic}`;
      } else {
        titlePrompt = `Invent a short, catchy title (2-3 words only) for a vocabulary box about everyday objects.`;
      }
      let title = await fetchOpenAiText(titlePrompt);
      // Remove quotes, extra punctuation, and keep only 2-3 words
      title = title.replace(/^"|"$/g, '').replace(/[.!?]+$/g, '').trim();
      const words = title.split(/\s+/).filter(Boolean);
      if (words.length > 3) title = words.slice(0, 3).join(' ');
      if (aiTitleInput) aiTitleInput.value = title;
    } catch (e) {
      console.error('[MintAI] generate failed:', e);
      aiPreview.textContent = `Error generating list: ${e?.message || 'Unknown error'}`;
    }
  };

  // Sentence generate button
  if (sentGenerateBtn) sentGenerateBtn.onclick = async () => {
    const wordPairs = parseLinesToPairs(aiWordlist.value);
    if (!wordPairs.length) return;
    if (!aiPreview) return;

    aiPreview.textContent = 'Generating sentences…';
    const difficulty = sentDiff?.value || 'easy';
    const patternDesc = (sentPatternDesc?.value || '').trim();
    const patternExamples = (sentPatternExamples?.value || '').trim();

    try {
      const prompt = buildSentencePrompt(wordPairs, {
        mode: sentenceMode,
        difficulty,
        patternDesc,
        patternExamples
      });
      const raw = await fetchOpenAiText(prompt);
      sentenceData = parseSentenceOutput(raw, wordPairs);
      renderSentencePreview(wordPairs);
    } catch (e) {
      console.error('[MintAI] sentence generate failed:', e);
      aiPreview.textContent = `Error generating sentences: ${e?.message || 'Unknown error'}`;
    }
  };

  if (aiClearBtn) aiClearBtn.onclick = () => { aiWordlist.value = ''; sentenceData = []; renderAiPreviewFromWordlist(); };

  if (aiInsertBtn) aiInsertBtn.onclick = async () => {
    const sourceText = (aiWordlist?.value || '').trim();
    const items = parseLinesToPairs(sourceText);
    if (!items.length) return;

    // Merge sentence data into items if available
    if (sentenceData.length) {
      for (let i = 0; i < items.length; i++) {
        const sd = sentenceData[i];
        if (sd) {
          if (sd.example) items[i].example = sd.example;
          if (sd.ex_kor) items[i].ex_kor = sd.ex_kor;
        }
      }
    }

    // Update main builder title from modal title
    if (aiTitleInput) {
      const mainTitleInput = document.getElementById('titleInput');
      if (mainTitleInput && aiTitleInput.value.trim()) {
        mainTitleInput.value = aiTitleInput.value.trim();
      }
    }
    const range = addItems(items); // {from, to}
    hideAiModal();
    // Auto-load images for the newly inserted range
    if (enablePicturesEl.checked) {
      for (let i = range.from; i <= range.to; i++) {
        const list = getList();
        if (!hasValidImageUrl(list[i].image_url)) {
          await loadImageForRow(list, i, loadingImages, render);
        }
      }
    }
    // Auto-load definitions for the newly inserted range
    if (enableDefinitionsEl.checked) {
      for (let i = range.from; i <= range.to; i++) {
        await generateDefinitionForRow(i);
      }
    }
    // Auto-load examples for words that DON'T already have sentences from the AI step
    if (enableExamplesEl && enableExamplesEl.checked && typeof generateExampleForRow === 'function') {
      for (let i = range.from; i <= range.to; i++) {
        const list = getList();
        // Skip if MINT AI already provided an example sentence
        if (list[i] && list[i].example && list[i].example.trim()) continue;
        await generateExampleForRow(i);
      }
    }
  };
}
